#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.."&&pwd)";. "$ROOT/scripts/tests/fair_launch_local_e2e_test_cleanup.sh";ACTIVE_RECORD='';ACTIVE_ROOT=''
fail(){ echo "signal_test: FAIL: $*" >&2;exit 1;}
cleanup(){ local original=$? ok=1;set +e;if [ -n "$ACTIVE_RECORD" ]&&[ -f "$ACTIVE_RECORD" ];then jc_fl_test_process_remove "$ACTIVE_RECORD" TERM||ok=0;fi;if [ -n "$ACTIVE_ROOT" ]&&[ -d "$ACTIVE_ROOT" ];then jc_fl_test_root_finalize "$ACTIVE_ROOT"||ok=0;fi;if [ "$ok" != 1 ];then echo "signal_test: cleanup retained evidence at $ACTIVE_ROOT" >&2;fi;trap - EXIT INT TERM;if [ "$original" -ne 0 ];then exit "$original";fi;[ "$ok" = 1 ]||exit 1;}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
wait_marker(){ local f="$1" m="$2" pid="$3";for _ in $(seq 1 600);do grep -Fq "$m" "$f" 2>/dev/null&&return 0;kill -0 "$pid" 2>/dev/null||break;sleep .1;done;return 1;}
record_ready(){ local root="$1" pid="$2" output="$3" script="$4" run="$5";local marker="$root/readiness.marker" record="$root/evidence/lifecycle.json";mkdir -p "$root/evidence";chmod 700 "$root/evidence";printf 'domain=JC_FL_SIGNAL_TEST_READY_V1\npid=%s\nstart=%s\nscript=%s\nrun=%s\nstateRoot=%s\noutput=%s\n' "$pid" "$(jc_fl_e2e_proc_start "$pid")" "$(realpath "$script")" "$run" "$(realpath "$root")" "$(realpath "$output")">"$marker";chmod 600 "$marker";jc_fl_test_process_record "$pid" "$marker" none "$root" "$record";ACTIVE_RECORD="$record";}
signal_record(){ local record="$1";jc_fl_test_process_remove "$record" TERM;ACTIVE_RECORD='';}
# Real TERM at final infrastructure seam: wrapper exit is not cleanup proof; exact immediate UUID runs are finalized.
S="$(jc_fl_test_root_create JC_FL_TEST_SIGNAL_START_V1)";chmod 700 "$S";ACTIVE_ROOT="$S";O="$S/out";JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_HOLD_AT=after_infrastructure_evidence bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$O" 2>&1 & PID=$!;wait_marker "$O" HOLD_AFTER_INFRASTRUCTURE_EVIDENCE "$PID"||fail start-hold;record_ready "$S" "$PID" "$O" "$ROOT/scripts/fair-launch/local-e2e/start.sh" none;signal_record "$ACTIVE_RECORD";rm -f "$S/readiness.marker";rmdir "$S/evidence" 2>/dev/null||true;wait "$PID"&&fail start-signal-success||true;! grep -q '^RUN_ID=' "$O"||fail start-success-output;jc_fl_test_root_finalize "$S"||fail interrupted-start-finalize;[ ! -e "$S" ]||fail interrupted-start-root-remains;ACTIVE_ROOT=''
# Injected finalization failure retains the root without stranding resources or deleting its evidence.
S="$(jc_fl_test_root_create JC_FL_TEST_SIGNAL_RETENTION_V1)";chmod 700 "$S";ACTIVE_ROOT="$S";O="$S/out";JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_HOLD_AT=after_infrastructure_evidence bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$O" 2>&1 & PID=$!;wait_marker "$O" HOLD_AFTER_INFRASTRUCTURE_EVIDENCE "$PID"||fail injected-start-hold;record_ready "$S" "$PID" "$O" "$ROOT/scripts/fair-launch/local-e2e/start.sh" none;signal_record "$ACTIVE_RECORD";rm -f "$S/readiness.marker";rmdir "$S/evidence" 2>/dev/null||true;wait "$PID"&&fail injected-start-signal-success||true;set +e;JC_FL_E2E_TEST_ROOT_FINALIZE_FAIL=1 jc_fl_test_root_finalize "$S";frc=$?;set -e;[ "$frc" -ne 0 ]&&[ -d "$S" ]&&[ -f "$S/root-finalization-failure" ]||fail injected-root-retention;jc_fl_test_root_finalize "$S"||fail injected-root-recovery;ACTIVE_ROOT=''
# Schema real-signal seams use the known run and bounded canonical teardown.
for seam in after_final_marker after_ready_state_rename after_final_verification;do S="$(jc_fl_test_root_create JC_FL_TEST_SIGNAL_SCHEMA_V1)";chmod 700 "$S";ACTIVE_ROOT="$S";out="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(echo "$out"|sed -n 's/^RUN_ID=//p')";d="$S/$run";O="$S/schema.out";JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_HOLD_AT="$seam" bash "$ROOT/scripts/fair-launch/local-e2e/apply-schema.sh" "$run">"$O" 2>&1&PID=$!;case "$seam" in after_final_marker)m=HOLD_AFTER_FINAL_MARKER;;after_ready_state_rename)m=HOLD_AFTER_READY_STATE_RENAME;;*)m=HOLD_AFTER_FINAL_VERIFICATION;;esac;wait_marker "$O" "$m" "$PID"||fail "$seam hold";record_ready "$S" "$PID" "$O" "$ROOT/scripts/fair-launch/local-e2e/apply-schema.sh" "$run";signal_record "$ACTIVE_RECORD";rm -f "$S/readiness.marker";rmdir "$S/evidence" 2>/dev/null||true;wait "$PID"&&fail "$seam signal success"||true;! grep -Fq 'schema ready:' "$O"||fail "$seam success output";JC_FL_E2E_STATE_ROOT="$S";jc_fl_e2e_load_state "$run";[ "$MYSQL_SCHEMA_READY" = 0 ]||fail "$seam state";[ ! -e "$d/credentials" ]&&[ ! -e "$d/evidence/database-schema.json" ]&&[ ! -e "$d/evidence/schema-readiness.json" ]||fail "$seam artifacts";jc_fl_test_bounded_teardown "$S" "$run"||fail "$seam teardown";jc_fl_test_root_finalize "$S"||fail "$seam root-finalize";ACTIVE_ROOT='';done
trap - EXIT INT TERM
echo 'fair_launch_local_e2e_signal_test: PASS wrapper identity, interrupted-run root finalization, retained failure evidence, and bounded schema teardown'
